	void skip(std::size_t length) {
		STREAM_READ_BOUNDS_ENFORCE(length, void());
		buffer_.skip(length);
	}

	/**
	 * @return The total number of bytes read from the stream.
	 */
	std::size_t total_read() const {
		return total_read_;
	}

	/**
