	 */
	std::size_t read_max() const {
		if(read_limit_) {
			assert(total_read_ < read_limit_);
			return read_limit_ - total_read_;
		} else {
			return buffer_.size();
		}
	}

	/** 
	 * @brief Get a pointer to the buffer read interface.
	 *
	 * @return Pointer to the buffer read interface. 
