			auto block = reinterpret_cast<free_block*>(storage + (block_size * i));
			push(block);
		}
	}

	inline void push(free_block* block) {
		assert(block);
		block->next = head_;
		head_ = block;
	}

	[[nodiscard]] inline free_block* pop() {
		if(!head_) {
			return nullptr;
		}

		auto block = head_;
		head_ = block->next;
		return block;
	}

public:
